new Function(script);
const checks = [
  ['doctype', /^<!doctype html>/i.test(html)],
  ['single main template', (html.match(/<main id="maincontent"/g) || []).length === 1],
  ['skip link', html.includes('href="#maincontent"')],
  ['single h1 template', (html.match(/<h1\b/g) || []).length === 1],
  ['primary nav labelled', html.includes('aria-label="Primary"')],
  ['footer nav labelled', html.includes('aria-label="Footer"')],
  ['live status', html.includes('aria-live="polite"')],
  ['cart name-label match', html.includes('aria-label="Cart, open cart with 2 items"')],
];
const failed = checks.filter(([, ok]) => !ok);
if (failed.length) {
  console.error('Failed checks:', failed.map(([name]) => name).join(', '));
  process.exit(1);
}
console.log('index.html syntax and structural checks passed');
