const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
(async () => {
  const browser = await chromium.launch();
  const viewports = [
    { name: 'desktop', width: 1280, height: 900 },
    { name: 'mobile-320', width: 320, height: 900 },
  ];
  const results = [];
  for (const viewport of viewports) {
    const page = await browser.newPage({ viewport });
    await page.goto('file://' + path.resolve('index.html'), { waitUntil: 'load' });
    await page.addScriptTag({ path: axePath });
    const result = await page.evaluate(async () => await window.axe.run());
    results.push({
      viewport: viewport.name,
      wcag: result.violations.filter(v => !v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
      bp: result.violations.filter(v => v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    });
    await page.close();
  }
  await browser.close();
  console.log(JSON.stringify(results));
  process.exit(results.some(r => r.wcag.length) ? 1 : 0);
})();
